// Validate that every entry in rawMissing is accounted for
for (const key of rawMissing) {
  if (!en[key]) throw new Error(`Missing EN translation for key: "${key}"`);
  if (!de[key]) throw new Error(`Missing DE translation for key: "${key}"`);
  if (!fr[key]) throw new Error(`Missing FR translation for key: "${key}"`);

  // Validate placeholder matching
  const keyPlaceholders = [...key.matchAll(/\{n\d\}/g)].map(m => m[0]).sort();
  for (const [lang, dict] of [['en', en], ['de', de], ['fr', fr]]) {
    const transPlaceholders = [...dict[key].matchAll(/\{n\d\}/g)].map(m => m[0]).sort();
    if (JSON.stringify(keyPlaceholders) !== JSON.stringify(transPlaceholders)) {
      throw new Error(`Placeholder mismatch for key "${key}" in ${lang}: expected ${JSON.stringify(keyPlaceholders)}, got ${JSON.stringify(transPlaceholders)}`);
    }
  }
}

const fileContent = `// Autogenerated and verified catalog of mayoral cockpit, scenario benchmarks, and systemic dynamics translations.
export default ${JSON.stringify({ en, de, fr }, null, 2)};
`;

fs.writeFileSync('src/locales/cockpit.js', fileContent, 'utf8');
console.log('Successfully generated src/locales/cockpit.js with', rawMissing.length, 'verified entries per language.');
